// Text-to-speech over the browser's speechSynthesis. Speech is generated by the browser or the operating
// system (Edge's "Natural" voices are streamed by Microsoft; most others are on the device). This module ranks
// voices (natural/neural first), plays a prosody plan (prosody.ts: chunks, pauses, gentle rate/pitch changes)
// and handles interruption. Nothing here is medical: it just says what it is given.
import { decimalWords, numberWords } from './numbers'
import { prosody } from './prosody'

export type Priority = 'normal' | 'urgent'
type VoiceLike = { name: string; lang: string; localService?: boolean; default?: boolean; voiceURI?: string }

export function ttsSupported(): boolean {
  return typeof window !== 'undefined' && 'speechSynthesis' in window && typeof SpeechSynthesisUtterance !== 'undefined'
}

/** Higher is better. Natural/neural voices first, then good named voices; novelty and robotic voices last. */
export function voiceScore(v: VoiceLike, lang = 'en'): number {
  const l = v.lang.toLowerCase().replace('_', '-')
  let s = 0
  if (l.startsWith(lang.toLowerCase())) s += 40
  else s -= 100
  if (l === 'en-gb') s += 6 // measured, slightly formal
  else if (l === 'en-us') s += 4
  else if (l.startsWith('en-')) s += 2
  if (/online \(natural\)/i.test(v.name)) s += 30 // Edge neural voices
  else if (/natural|neural/i.test(v.name)) s += 22
  if (/^google\b/i.test(v.name)) s += 14
  if (/enhanced|premium|\bsiri\b/i.test(v.name)) s += 16
  if (/google uk english male|daniel|oliver|arthur|ryan|guy|aria|jenny|samantha|karen|serena|moira|libby|sonia|ava|andrew|emma|brian|thomas|maisie/i.test(v.name)) s += 10
  if (/espeak|compact|novelty|bad news|bahh|bells|boing|bubbles|cellos|good news|jester|organ|superstar|trinoids|whisper|wobble|zarvox|albert|fred|junior|kathy|ralph|grandma|grandpa|eddy|flo|reed|rocko|sandy|shelley/i.test(v.name)) s -= 40
  if (v.localService) s += 1
  if (v.default) s += 1
  return s
}

/** Prefer a calm, natural English voice. Pure so it can be tested. */
export function pickVoice(voices: VoiceLike[], lang = 'en'): number {
  if (!voices.length) return -1
  let best = 0
  let bestScore = -Infinity
  voices.forEach((v, i) => {
    const sc = voiceScore(v, lang)
    if (sc > bestScore) {
      bestScore = sc
      best = i
    }
  })
  return best
}

export type VoiceOption = { uri: string; name: string; lang: string; natural: boolean; score: number }

/** English voices on this device, best first, for the voice picker. */
export function rankVoices(voices: VoiceLike[]): VoiceOption[] {
  return voices
    .map((v) => ({ uri: v.voiceURI ?? v.name, name: v.name, lang: v.lang, natural: /natural|neural|enhanced|premium|^google/i.test(v.name), score: voiceScore(v) }))
    .filter((v) => v.score > 20)
    .sort((a, b) => b.score - a.score || a.name.localeCompare(b.name))
}

/** Older callers: split into sentence-sized chunks (Chrome silently stops utterances longer than ~15 s). */
export function chunkText(text: string, max = 220): string[] {
  const parts = text
    .replace(/\s+/g, ' ')
    .trim()
    .split(/(?<=[.!?;:])\s+/)
    .filter(Boolean)
  const out: string[] = []
  for (const p of parts) {
    if (p.length <= max) {
      out.push(p)
      continue
    }
    let rest = p
    while (rest.length > max) {
      const cut = rest.lastIndexOf(',', max - 1) > 60 ? rest.lastIndexOf(',', max - 1) + 1 : rest.lastIndexOf(' ', max)
      out.push(rest.slice(0, cut > 0 ? cut : max).trim())
      rest = rest.slice(cut > 0 ? cut : max).trim()
    }
    if (rest) out.push(rest)
  }
  return out
}

type Job = { text: string; priority: Priority; rate: number; pitch: number; pauseAfter: number; onEnd?: () => void }

let voiceCache: SpeechSynthesisVoice[] = []
let queue: Job[] = []
let current: Job | null = null
let rate = 1
let preferred: string | null = null
let onActivity: ((speaking: boolean) => void) | null = null
const voiceListeners = new Set<() => void>()
let epoch = 0
let gapTimer: ReturnType<typeof setTimeout> | undefined

function loadVoices() {
  if (!ttsSupported()) return
  voiceCache = window.speechSynthesis.getVoices()
  voiceListeners.forEach((f) => f())
}

if (ttsSupported()) {
  loadVoices()
  window.speechSynthesis.addEventListener?.('voiceschanged', loadVoices)
}

/* ---------- guard: speech never outlives the page, and does not go on in a page nobody is looking at ---------- */

/** a hidden page stops non-urgent speech after this long (emergency instructions are allowed to finish) */
export const HIDDEN_SPEECH_MS = 3000

type GuardTarget = { addEventListener: (type: string, fn: () => void) => void; removeEventListener: (type: string, fn: () => void) => void }

/**
 * Installs the page-lifecycle guard on `win` / `doc`:
 *  - pagehide / beforeunload: everything queued is dropped and the engine is cancelled at once (the browser's
 *    speech engine is shared and can otherwise go on talking after the tab is closed or navigated away);
 *  - the page hidden for `hiddenMs`: non-urgent speech is cancelled; urgent speech may finish.
 * `cancel` / `urgentNow` are injected for tests. Returns the uninstall function.
 */
export function installSpeechGuard(
  win: GuardTarget,
  doc: GuardTarget & { readonly hidden: boolean },
  deps: { cancel: () => void; urgentNow: () => boolean; hiddenMs?: number } = { cancel: cancelSpeech, urgentNow: speakingUrgent },
): () => void {
  let timer: ReturnType<typeof setTimeout> | undefined
  const leave = () => {
    clearTimeout(timer)
    deps.cancel()
  }
  const visibility = () => {
    clearTimeout(timer)
    if (!doc.hidden) return
    timer = setTimeout(() => {
      if (doc.hidden && !deps.urgentNow()) deps.cancel()
    }, deps.hiddenMs ?? HIDDEN_SPEECH_MS)
  }
  win.addEventListener('pagehide', leave)
  win.addEventListener('beforeunload', leave)
  doc.addEventListener('visibilitychange', visibility)
  return () => {
    clearTimeout(timer)
    win.removeEventListener('pagehide', leave)
    win.removeEventListener('beforeunload', leave)
    doc.removeEventListener('visibilitychange', visibility)
  }
}

if (typeof window !== 'undefined' && typeof document !== 'undefined' && ttsSupported()) {
  // a page that was closed while speaking (or reloaded) may have left the shared engine talking: silence it first
  try {
    window.speechSynthesis.cancel()
  } catch {
    /* nothing to cancel */
  }
  installSpeechGuard(window, document)
}

export function setRate(r: number) {
  rate = Math.min(1.3, Math.max(0.7, r))
}

/** Use this voice (voiceURI) when it exists on the device; null = best ranked. */
export function setVoicePreference(uri: string | null) {
  preferred = uri
}

/** The English voices available now, best first. */
export function availableVoices(): VoiceOption[] {
  if (!voiceCache.length) loadVoices()
  return rankVoices(voiceCache)
}

/** Voices load asynchronously in Chrome; subscribe to refresh a picker. Returns an unsubscribe function. */
export function onVoicesChanged(fn: () => void): () => void {
  voiceListeners.add(fn)
  return () => voiceListeners.delete(fn)
}

function chosenVoice(): SpeechSynthesisVoice | null {
  if (!voiceCache.length) loadVoices()
  if (preferred) {
    const v = voiceCache.find((x) => x.voiceURI === preferred || x.name === preferred)
    if (v) return v
  }
  const i = pickVoice(voiceCache, 'en')
  return i >= 0 ? voiceCache[i] : null
}

/** Called with true when speech starts and false when everything queued has been said. */
export function onSpeaking(fn: ((speaking: boolean) => void) | null) {
  onActivity = fn
}

export function isSpeaking(): boolean {
  return current !== null || queue.length > 0
}

/** urgent (emergency) speech is being said or waiting */
export function speakingUrgent(): boolean {
  return current?.priority === 'urgent' || queue.some((j) => j.priority === 'urgent')
}

function pump() {
  if (current || !queue.length) {
    if (!current && !queue.length) onActivity?.(false)
    return
  }
  const job = queue.shift()!
  current = job
  onActivity?.(true)
  const my = epoch
  let guard: ReturnType<typeof setTimeout> | undefined
  let finished = false
  const done = () => {
    clearTimeout(guard)
    if (finished || my !== epoch || current !== job) return
    finished = true
    current = null
    job.onEnd?.()
    // a short, natural breath between sentences and clauses
    if (queue.length && job.pauseAfter > 0) {
      onActivity?.(true)
      gapTimer = setTimeout(() => my === epoch && pump(), job.pauseAfter)
    } else pump()
  }
  try {
    const u = new SpeechSynthesisUtterance(job.text)
    const v = chosenVoice()
    if (v) {
      u.voice = v
      u.lang = v.lang
    } else u.lang = 'en-GB'
    u.rate = job.rate
    u.pitch = job.pitch
    u.volume = 1
    u.onend = done
    u.onerror = done
    // some engines never fire "end" (no voices installed, tab in background): do not stall the queue
    guard = setTimeout(done, 2500 + (job.text.length * 90) / job.rate)
    window.speechSynthesis.speak(u)
  } catch {
    done()
  }
}

/** Stop everything now (barge-in: the person started talking, or asked AURA to be quiet). */
export function cancelSpeech() {
  epoch++
  clearTimeout(gapTimer)
  queue = []
  const had = current !== null
  current = null
  if (ttsSupported()) {
    try {
      window.speechSynthesis.cancel()
    } catch {
      /* nothing to cancel */
    }
  }
  if (had) onActivity?.(false)
}

/**
 * Say `text`. `urgent` interrupts whatever is being said and jumps the queue; `normal` waits its turn.
 * `slower` (e.g. "repeat that slower") multiplies the rate. Returns false when speech is unavailable
 * (the caller still shows the text as a caption).
 */
export function speak(text: string, opts: { priority?: Priority; onEnd?: () => void; slower?: number } = {}): boolean {
  if (!ttsSupported() || !text.trim()) {
    opts.onEnd?.()
    return false
  }
  const priority = opts.priority ?? 'normal'
  // nobody is looking at this page: only urgent speech may start (it is shown as a caption either way)
  if (priority !== 'urgent' && typeof document !== 'undefined' && document.hidden) {
    opts.onEnd?.()
    return false
  }
  if (priority === 'urgent') cancelSpeech()
  const chunks = prosody(text, { rate: rate * (opts.slower ?? 1), urgent: priority === 'urgent' })
  if (!chunks.length) {
    opts.onEnd?.()
    return false
  }
  chunks.forEach((c, i) => queue.push({ ...c, priority, onEnd: i === chunks.length - 1 ? opts.onEnd : undefined }))
  pump()
  return true
}

/* ---------- pronunciation helpers (pure) ---------- */

export const sayBloodPressure = (sys: number, dia: number) => `${Math.round(sys)} over ${Math.round(dia)}`
export const sayPercent = (n: number) => `${numberWords(Math.round(n))} percent`
export const sayTemperature = (c: number) => `${decimalWords(c, 1)} degrees Celsius`
export const sayHours = (h: number) => {
  const r = Math.round(h * 10) / 10
  return `${Number.isInteger(r) ? numberWords(r) : decimalWords(r, 1)} ${r === 1 ? 'hour' : 'hours'}`
}
export const sayLitres = (l: number) => {
  const r = Math.round(l * 100) / 100
  return `${decimalWords(r, r * 10 === Math.round(r * 10) ? 1 : 2)} ${r === 1 ? 'litre' : 'litres'}`
}
export const sayCount = (n: number, unit: string) => `${numberWords(Math.round(n))} ${unit}`
